		strategy.setQueryEvaluationMode(mode);
		strategy.setOptimizerPipeline(() -> List.of(new QueryModelNormalizerOptimizer()));
		strategy.optimize(query, new EvaluationStatistics(), EmptyBindingSet.getInstance());
